import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        long target = ((long) n * (n + 1) / 2 + 1) / 2;
        int lo = 1, hi = n;
        int[] counts = new int[n + 1];
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            Arrays.fill(counts, 0);
            long total = 0;
            int left = 0, distinct = 0;
            // Count subarrays with at most mid distinct values via a sliding window.
            for (int right = 0; right < n; right++) {
                if (counts[a[right]]++ == 0) distinct++;
                while (distinct > mid) if (--counts[a[left++]] == 0) distinct--;
                total += right - left + 1;
            }
            if (total >= target) hi = mid; else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int, n)
	for i := range a {
		a[i] = int(nextInt())
	}
	target := (int64(n)*int64(n+1)/2 + 1) / 2
	lo, hi := 1, n
	counts := make([]int, n+1)
	for lo < hi {
		mid := (lo + hi) / 2
		clear(counts)
		total := int64(0)
		left, distinct := 0, 0
		// Count subarrays with at most mid distinct values via a sliding window.
		for right := 0; right < n; right++ {
			if counts[a[right]] == 0 {
				distinct++
			}
			counts[a[right]]++
			for distinct > mid {
				counts[a[left]]--
				if counts[a[left]] == 0 {
					distinct--
				}
				left++
			}
			total += int64(right - left + 1)
		}
		if total >= target {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	fmt.Println(lo)
}
